#include <stdio.h>

// 1. Dangerous macro
#define SQUARE_BAD(x) x * x

// 2. Safer macro
#define SQUARE_SAFE(x) ((x) * (x))

int main() {
    int a = 5;

    // Expected: 36, Actual: 5 + 1 * 5 + 1 = 11
    printf("Bad: %d\n", SQUARE_BAD(a + 1));

    // Expected: 36, Actual: ((5 + 1) * (5 + 1)) = 36
    printf("Safe: %d\n", SQUARE_SAFE(a + 1));

    // Side Effect Pitfall (Double Evaluation)
    int n = 3;
    // Becomes ((n++) * (n++)) -> n increases twice!
    printf("Side Effect: %d\n", SQUARE_SAFE(n++)); 

    return 0;
}
